      const [bx, bz] = stOff(S.rel, stAng(S.rel, S.m1), 200); let B = null; dropship(bx, bz, () => { B = stBig(mkMech(bx, bz, { ...PRESETS[17], paint: FAC.maw.paint }, 1, { name: 'THE PALLBEARER', hpK: 2.2, skill: 1.3 }), 1.2); B.alert = true; B.focus = rel; fieldWho(cap, B); W = W.concat(hot1(foes(.8, bx, bz, 6, 36, mp))); nav('b', B, 'THE PALLBEARER', '#ff5a3a'); }, undefined, 1);
      await until(() => B); look(B, 'THE PALLBEARER'); await tell(cap, 'Evening, brothers, sisters. Lovely service. We have come for the box. We will carry it very carefully, we are known for it, and none of you need be in it.');
      setObj('b', () => `Bring down THE PALLBEARER — ${irHull(B)}`); await until(() => B.dead && alive(W) <= 1); unnav('b'); unnav('r'); setObj('b', null, 1); setObj('m', null, 1);
