      for (const [i, k] of ['c1', 'c2', 'c3'].entries()) { nav('c', S[k], `CRATER ${i + 1}`, '#ffe0a0'); await stHold('c', S[k], 30, 7, `Stand in crater ${i + 1} while Mira takes the bearing`); chatter(mira, said[i]); if (i === 0) chatter(hd, 'Envoy Anselm. For the record, the Combine regards that crater as conclusive evidence of Karsk bad faith, whatever the monitor finds in it.'); if (i === 1) chatter(kd, 'Radek. If the monitor finds it is Helion, I want it in writing before the ink is dry. If the monitor finds it is us, the monitor is mistaken.'); }
      /* the battery that belongs to nobody */
