/* ---- BORROWED THUNDER: the cruiser OBSTINATE, on our side. A capital ship's hull and her turrets and engines are separate entities; btShip() says something about all of them at once ---- */
const btShip = (e, o) => { Object.assign(e, o); for (const s of e.subs) if (!s.dead) Object.assign(s, o, { tgt: null, tT: 0 }); return e; };
/* her spinal gun, laid by the player: the hostile thing on the ground nearest the line of the reticle, within about two degrees of it and nine hundred metres. Ground in the way does not matter (the round
   comes from overhead), which is as well: a battery seen across a kilometre of dunes is mostly behind one */
function btMark() {
  const c = FD.camera.position, fx = P.aim.x - c.x, fy = P.aim.y - c.y, fz = P.aim.z - c.z, fl = Math.hypot(fx, fy, fz) || 1; let b = null, bs = 1;
  for (const e of FD.t0) { if (e.dead || e.team !== 1 || e.kind === 'ship' || e.of || e.kind === 'drone') continue; const vx = e.pos.x - c.x, vy = e.pos.y + (e.cy || 0) - c.y, vz = e.pos.z - c.z, t = (vx * fx + vy * fy + vz * fz) / fl; if (t < 20 || t > 900) continue; const q = Math.hypot(vx - fx / fl * t, vy - fy / fl * t, vz - fz / fl * t) / (10 + t * .035); if (q < bs) { bs = q; b = e; } }
  return b;
}
function btFire(ship, e) {
  const x = e.pos.x, z = e.pos.z, bm = hot(0xffd27a, 6); bm.transparent = true; bm.blending = THREE.AdditiveBlending; bm.depthWrite = false; addBeam(ship.pos.clone(), V3(x, heightAt(x, z), z), bm, .7, 2.4); shell(x, z, e.kind === 'struct' ? 2600 : 380, 22, 2.4, 0); if (ship.pos.distanceTo(P.pos) < 520) sfx.play('ion', .9);
}

